  ui_story_5079_50790100_85_dialog_content = "ฉันรู้สึกเป็นเกียรติที่ได้แบ่งปันรถไฟนี้กับคุณวันนี้ ท่านหญิง ขอให้เดินทางปลอดภัย...",
  ui_story_5079_50790100_86_dialog_content = "ท-ขอบคุณ.",
  ui_story_5079_50790100_87_dialog_content = "แปลกมาก... คนคนนั้นเมื่อกี๊เป็นอะไร? เสื้อผ้าเหล่านี้มีเวทมนตร์หรืออะไรเช่นนั้นเหรอ?",
  ui_story_5079_50790100_88_dialog_content = "แล้วทำไมฉันรู้สึกเหมือนเคยเห็นเขาที่ไหนมาก่อนนะ?",
  ui_story_5079_50790100_89_dialog_content = "อ๊ะ, ลืมมันไปเถอะ ตอนนี้ไม่ใช่เวลามากังวลเรื่องเหล่านี้...",
  ui_story_5079_50790100_90_dialog_content = "*ฟืดด*",
  ui_story_5079_50790100_91_dialog_content = "ว้าว, กลิ่นเหล่านั้น... เนื้อและมะเขือเทศ! คุกกี้ครีมและขนมปังอบสด! และอื่น ๆ อีก...",
  ui_story_5079_50790100_92_dialog_content = "นั่นแหละ ฟอลต้า! เรายังไม่ได้ออกจากรถไฟ แต่ฉันสามารถได้กลิ่นอาหารที่หอมหวานมากมายแล้ว!",
  ui_story_5079_50790100_93_dialog_content = "ดูเหมือนว่าเราจะต้องลองชิมอาหารท้องถิ่นสักหน่อยก่อนที่จะเริ่มทำธุระเลย!",
  ui_story_5079_50790100_94_dialog_content = "!",
  ui_story_5079_50790200_1_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5079_50790200_2_dialog_content = "นี่คือฟอลต้า!",
  ui_story_5079_50790200_3_dialog_content = "สถาปัตยกรรมที่นี่เป็นเอกลักษณ์มาก ดูเหมือนว่าสถานที่นี้จะหลงไหลในอาหารมากกว่าอัมบราตัน!",
  ui_story_5079_50790200_4_dialog_content = "หือ? หรือว่าบ้านพวกนี้ถูกสร้างจากวัตถุดิบจริงๆเหรอ?",
  ui_story_5079_50790200_5_dialog_content = "<color=#e8d9bb>ชูโอ—</color>",
  ui_story_5079_50790200_6_dialog_content = "อ๊ะ...ฉันจะพลาดรถไฟแล้ว! ขอโทษค่ะ!",
  ui_story_5079_50790200_7_dialog_content = "เอ๋?",
  ui_story_5079_50790200_8_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5079_50790200_9_dialog_content = "โอ๊ย...",
  ui_story_5079_50790200_10_dialog_content = "ฉันเพิ่งซื้อเสื้อผ้าเหล่านี้มาเอง! แน่ๆ ตอนนี้พวกมันสกปรกแน่นอน!",
  ui_story_5079_50790200_11_dialog_content = "หืม? พวกมันไม่สกปรกเลยนะ แท้จริงแล้วพวกมันกลิ่นหวาน... รอสักครู่ หินที่อยู่บนพื้นนี้ทำจากลูกอมหรือเปล่านะ?",
  ui_story_5079_50790200_12_dialog_content = "...",
  ui_story_5079_50790200_13_dialog_content = "ฉันสงสัยว่ามันจะมีรสชาติยังไงนะ? ฉันมักจะกินหินลูโมโปลิสเพื่อช่วยย่อยอาหาร ดังนั้นการกินเพียงข้าวเม็ดเดียวไม่น่าจะทำให้เจ็บ...",
  ui_story_5079_50790200_14_dialog_content = "เอ๋!",
  ui_story_5079_50790200_15_dialog_content = "ห๊ะ",
  ui_story_5079_50790200_16_dialog_content = "คุณคิดว่าคุณกำลังทำอะไรอยู่หรือคะ นางสาว? หินพวกนี้ไม่ใช่สำหรับการรับประทานนะคะ!",
  ui_story_5079_50790200_17_dialog_content = "เหอะ คุณน่ะ... แล้วคุณคือใครที่จะบอกฉันว่าฉันไม่สามารถกินมันได้ล่ะ?",
  ui_story_5079_50790200_18_dialog_content = "คุณดูเหมือนว่าไม่เข้าใจ ซึ่งหมายความว่าคุณอาจจะไม่ใช่คนแถวนี้",
  ui_story_5079_50790200_19_dialog_content = "หินเหล่านี้เป็นอาหารสำหรับ<color=#FFB400>นกกระจอกลูกอม</color> ด้วยความช่วยเหลือจากพวกเขาเราจึงสามารถสร้างอาคารของเราจากอาหารได้!",
  ui_story_5079_50790200_20_dialog_content = "คุณจะคิดยังไงถึงจะทำให้สัตว์ที่ทำงานหนักเหล่านี้ขาดอาหารได้ล่ะ?",
  ui_story_5079_50790200_21_dialog_content = "เธอหมายความว่า ตึกทั้งหมดที่นี่จริงๆ แล้วทำจากอาหารหรอ?",
  ui_story_5079_50790200_22_dialog_content = "อืม! แค่มองรอบ ๆ ก็จะเห็นว่า ไม้พื้นทำจากเมล็ดโกโก้ และโคมไฟถนนก็คืออมยิ้มที่ส่องสว่าง...",
  ui_story_5079_50790200_23_dialog_content = "เฮ้! คุณกำลังทำอะไรกับโคมไฟถนนนั่น?",
  ui_story_5079_50790200_24_dialog_content = "การลงโทษสำหรับการทำลายทรัพย์สินสาธารณะนั้นรุนแรงมาก! พวกเขาจะแขวนคุณอยู่กลางถนนแล้วปล่อยนกกระจอกลูกอมมาเจาะคุณจนแตก...",
  ui_story_5079_50790200_25_dialog_content = "คุณไม่รู้อะไรเกี่ยวกับที่นี่เลยเหรอ?",
  ui_story_5079_50790200_26_dialog_content = "ฟังดูเหมือนเป็นเรื่องโกหกเลยนะ คุณแน่ใจไหมว่าคุณไม่ได้แต่งเรื่องขึ้นมาทั้งหมด?",
  ui_story_5079_50790200_27_dialog_content = "เธอล้อเล่นหรือ? นั่นแหละเหตุผลที่ถนนของฟอลต้าสะอาดและเรียบร้อยเสมอ!",
  ui_story_5079_50790200_28_dialog_content = "คุณรู้ไหมคะ... แม้ว่าคุณจะสวมเสื้อผ้าที่ดูดีและซับซ้อน แต่คุณก็ทำตัวไม่ต่างจากเด็กน้อยเลยนะคะ",
  ui_story_5079_50790200_29_dialog_content = "คงจะเป็นเพราะท่านพ่อฉันโกหกเมื่อพูดว่าคนที่แต่งตัวดีจะประพฤติดีกว่าคนอื่น!",
  ui_story_5079_50790200_30_dialog_content = "บอกมา... คุณไม่ได้ขโมยชุดนั้นไปใช่ไหม? ใช่ไหม?",
  ui_story_5079_50790200_31_dialog_content = "หืม? ฉันขอให้คุณรู้ว่าฉันได้จ่ายเงินมากมายในเสื้อผ้าเหล่านี้นะ...",
  ui_story_5079_50790200_32_dialog_content = "(ฮึ่ม, ฉันไม่จำเป็นต้องนั่งทนฟังจากสาวน้อยแบบนี้นะ.)",
  ui_story_5079_50790200_33_dialog_content = "(เธอไม่มีความเคารพต่อผู้ใหญ่ หรือขอบเขตใด ๆ ที่เกี่ยวข้อง... แต่ด้วยเหตุผลบางอย่าง ท่าทางน่ารำคาญของเธอดูคุ้นเคยอย่างแปลกประหลาด)",
  ui_story_5079_50790200_34_dialog_content = "อืม... ฉันรู้สึกว่าการชนกับท่านหญิงแปลก ๆ คนนี้ทำให้ฉันลืมอะไรสักอย่าง...",
  ui_story_5079_50790200_35_dialog_content = "<color=#e8d9bb>ชูโอโอโอโอโอโอ—</color>",
  ui_story_5079_50790200_36_dialog_content = "โอ้ เฮ้ย, รถไฟ! มันออกไปแล้ว!",
  ui_story_5079_50790200_37_dialog_content = "นี่เป็นความผิดของคุณทั้งหมด! คุณชนฉันก่อน แล้วคุณทำให้ฉันเสียเวลากับการเล่นงานของคุณ และในที่สุดฉันก็พลาดรถไฟ!",
  ui_story_5079_50790200_38_dialog_content = "แผนการหนีจากบ้านของฉันล้มเหลวแล้ว! ฉันหวังว่าคุณพร้อมที่จะชดใช้ให้ฉันนะ!",
  ui_story_5079_50790200_39_dialog_content = "หืม? คุณกำลังหนีเหรอ? แล้วคุณหมายถึงอะไรว่า \"ชดเชยฉัน\" ล่ะ?",
  ui_story_5079_50790200_40_dialog_content = "คุณนี่แหละคนที่ชนฉัน... ถ้าจะมีอะไร คุณควรจะชดใช้ฉัน!",
  ui_story_5079_50790200_41_dialog_content = "อีกทั้งฉันยังช่วยคุณอย่างมากด้วยการขัดขวางแผนการหนีของคุณ การขอบคุณก็จะดีนะ คุณไม่คิดเช่นนั้นหรือ?",
  ui_story_5079_50790200_42_dialog_content = "หืม? ถ้าคิดว่าฉันควรขอบคุณคุณ คุณคงฝัน! นอกจากนี้ คุณคงถูกแกะสลักเป็นชิ้นๆ ถ้าไม่มีฉันอยู่!",
  ui_story_5079_50790200_43_dialog_content = "ถ้ามีใครควรจะขอบคุณที่นี่ นั่นคือคุณ!",
  ui_story_5079_50790200_44_dialog_content = "อย่าเข้าใจผิดนะเด็ก! ฉันทำแบบนั้นเพราะฉันกำลังวิจัยวัตถุดิบเท่านั้นเอง!",
  ui_story_5079_50790200_45_dialog_content = "คุณไม่ได้คิดว่าฉันจะกินหินเพราะฉันหิวใช่ไหม? ใช่ไหม?",
  ui_story_5079_50790200_46_dialog_content = "แล้วตอนนี้นายก็เริ่มก็อปปี้ฉัน! อ่า... นายนี่ยังเป็นเด็กอยู่จริง ๆ นะ รู้ตัวมั้ย?",
  ui_story_5079_50790200_47_dialog_content = "ฉันเบื่อการทะเลาะกับเด็กคนนี้แล้ว ฉันยังต้องไปช้อปปิ้งเยอะมาก และยังต้องไปเยี่ยมชมร้านค้าหลาย ๆ แห่งและเปรียบเทียบราคาอีก",
  ui_story_5079_50790200_48_dialog_content = "... ด-เดี๋ยวก่อน!",
  ui_story_5079_50790200_49_dialog_content = "อะไรตอนนี้?",
  ui_story_5079_50790200_50_dialog_content = "คุณมาที่นี่เพื่อซื้อส่วนผสมใช่มั้ย? นั่นแหละคือธุรกิจของครอบครัวเรา! อยากจะมาที่ร้านของเรามั้ย?",
  ui_story_5079_50790200_51_dialog_content = "ตอนนี้คุณต้องการธุรกิจของฉันหลังจากที่โต้เถียงกันเยอะแยะหรือ? ขอโทษนะ แต่ฉันไม่สนใจ",
  ui_story_5079_50790200_52_dialog_content = "<size=30>*เฮ้อ* ล้มเหลวอีกครั้ง...</size>",
  ui_story_5079_50790200_53_dialog_content = "(พ่อมักจะบอกว่าเราไม่สามารถยอมแพ้ในการทำธุรกิจกับลูกค้าร่ำรวยอย่างเธอได้...)",
  ui_story_5079_50790200_54_dialog_content = "(ถ้าฉันสามารถทำให้เธอมาที่ร้านของเรา... ฉันเดาว่าพ่อคงจะยกย่องฉันเยอะเลย! บางทีเขาอาจจะลืมเรื่องที่เกิดขึ้นในวันหลายวันที่ผ่านมาไปด้วย)",
  ui_story_5079_50790200_55_dialog_content = "(แต่สำคัญที่สุด ฉันสามารถใช้โอกาสนี้เพื่อกำจัดทุกสิ่งที่ฉันไม่ชอบที่จะกิน... ฮิฮิฮิ!)",
  ui_story_5079_50790200_56_dialog_content = "ฉ-ฉันสามารถขอพ่อฉันให้ส่วนลดมหาศาลให้คุณได้! คิดว่ามันเป็นวิธีของฉันในการชดเชยคุณ!",
  ui_story_5079_50790200_57_dialog_content = "คุณไม่ใช่กำลังพยายามหนีจากบ้านหรอ? ทำไมคุณถึงพาคนแปลกหน้ากลับบ้านแล้วขอส่วนลดล่ะ?",
  ui_story_5079_50790200_58_dialog_content = "ถ้าผมเป็นพ่อของคุณ ผมคงไม่เคยตกลงกับอะไรแบบนั้นเลย",
  ui_story_5079_50790200_59_dialog_content = "*ฮึก* ฉ-ฉันควรทำยังไงดี",
  ui_story_5079_50790200_60_dialog_content = "ฉันเข้าใจแล้ว! ฉันจะบอกเขาว่าคุณกังวลเรื่องความปลอดภัยของฉัน ดังนั้นคุณจึงพาฉันกลับบ้าน! เขาจะขอบคุณมากจนเสนอข้อเสนอที่มีครั้งเดียวในชีวิตให้คุณ!",
  ui_story_5079_50790200_61_dialog_content = "ฟังดูมีเหตุผล... ฉันเดาว่าการทำความดีครั้งหนึ่งไม่น่าจะทำให้เราเจ็บปวด",
  ui_story_5079_50790200_62_dialog_content = "จำไว้นะ ฉันไม่สามารถสัญญาได้ว่าจะทำธุรกิจกับครอบครัวของเจ้าหนู นำทางไปเลยล่ะ",
  ui_story_5079_50790200_63_dialog_content = "เอ๊ะ? นั่นอะไรข้างหลังเธอน่ะ?",
  ui_story_5079_50790200_64_dialog_content = "คุณสังเกตุได้ที่สุดแล้วสินะ? ยังไม่สายเกินไปที่จะกลัวนะ! โดยเฉพาะตอนนี้ที่คุณรู้แล้วว่าจะเกิดอะไรขึ้นถ้าคุณทำให้ฉันโกรธ...",
  ui_story_5079_50790200_65_dialog_content = "ว้าว, น่ารักจัง! และดูสิ, มันเคลื่อนไหวได้ด้วยตัวเอง! ฉันจะเลี้ยงมันได้ไหม? ได้ไหม?",
  ui_story_5079_50790200_66_dialog_content = "เฮ้ย, หยุดเถอะ! นี่ไม่ใช่ของเล่นนะ!",
  ui_story_5079_50790200_67_dialog_content = "ทำไมคุณถึงโกรธขนาดนี้? ฉันแค่อยากลูบเพื่อนตัวเล็กของคุณ...",
  ui_story_5079_50790200_68_dialog_content = "\"เพื่อนน้อย\" ของฉันเหรอ? คุณคิดว่าหินแห่งการล่าคือ... อืม, ลืมมันเถอะ.",
  ui_story_5079_50790200_69_dialog_content = "เคาะตัวเองออกเลยลูก แต่ทุกครั้งที่คุณลูบมัน คุณต้องให้ส่วนลดใหญ่ขึ้นอีกนะ",
  ui_story_5079_50790200_70_dialog_content = "เออ-เอาล่ะ... ฉันจะลูบมันแค่ครั้งเดียว...",
  ui_story_5079_50790200_71_dialog_content = "!",
  ui_story_5079_50790200_72_dialog_content = "ว้าว, น่ารักจริงๆ! มันเขยิบมาหาฉัน, ดังนั้นการลูบครั้งสุดท้ายไม่นับนะ!",
  ui_story_5079_50790200_73_dialog_content = "!",
  ui_story_5079_50790200_74_dialog_content = "(หินแห่งการล่าปล่อยให้เธอสัมผัส? ทำไมเถียง กงล้อไร้ประโยชน์!)",
  ui_story_5079_50790200_75_dialog_content = "เอาล่ะ พอแล้ว! ไปกันเลย!",
  ui_story_5079_50790300_1_dialog_content = "อืม, อืม, อืม!",
  ui_story_5079_50790300_2_dialog_content = "... คุณมีความสุขมากเกี่ยวกับอะไร?",
  ui_story_5079_50790300_3_dialog_content = "คุณเป็นลูกค้าใหญ่คนแรกที่ฉันเคยพากลับบ้านมา ดังนั้นฉันแน่นอนว่าฉันมีความสุข! พ่อจะภูมิใจในฉันมากเลย!",
  ui_story_5079_50790300_4_dialog_content = "คุณมักจะช่วยงานธุรกิจของครอบครัวบ้างไหม?",
  ui_story_5079_50790300_5_dialog_content = "เออ... แต่ฉันมักจะเป็นปัญหาเสมอ แท้จริงแล้วฉันคิดว่าฉันเป็นสาเหตุที่ทำให้ร้านของเราไม่ค่อยดีในช่วงนี้นะ",
  ui_story_5079_50790300_6_dialog_content = "แต่ตอนนี้ที่คุณมาถึงที่นี่แล้ว, สถานการณ์อาจจะดีขึ้นสำหรับเราในที่สุด!",
  ui_story_5079_50790300_7_dialog_content = "...ฉันยังไม่รู้ชื่อของคุณเลย เด็กน้อย.",
  ui_story_5079_50790300_8_dialog_content = "ผมเนี่ยนะ?",
  ui_story_5079_50790300_9_dialog_content = "ห๊ะ",
