  ui_story_5079_50790300_20_dialog_content = "?",
  ui_story_5079_50790300_21_dialog_content = "ฉันไม่เห็นจะเข้าใจที่แกพูดเลย!",
  ui_story_5079_50790300_22_dialog_content = "พ่อฉันรักร้านของเขามาก และเขาเปิดร้านทุกวันในทุกปี! มันจะปิดได้อย่างไรล่ะ?",
