  ui_story_5079_50790300_24_dialog_content = "(ฉันรู้ว่าฉันไม่ควรมีส่วนร่วมกับเด็กคนนี้ ฉันเสียเวลามากมายแล้ว)",
  ui_story_5079_50790300_25_dialog_content = "(ถ้าฉันไม่ทำให้สำเร็จอย่างสมบูรณ์ ไม่รู้ว่าพวกเขาจะล้อเล่นฉันแค่ไหน...)",
