  ui_story_5079_50790300_36_dialog_content = "แต่การทะเลาะกับพ่อนั่นเป็นเรื่องปกติใช่ไหม?",
  ui_story_5079_50790300_37_dialog_content = "*ฟืดด*... นั่นหมายความว่าคุณก็ทะเลาะกับพ่อเหรอ?",
  ui_story_5079_50790300_38_dialog_content = "ฉันทำแล้ว และมันก็แย่มากเลย พี่เขาปฏิเสธที่จะรับฉันหรือหินแห่งการล่าของฉันที่นี่— ตัวที่คุณคิดว่าน่ารักนั่นแหละ",
