  ui_story_5079_50790300_76_dialog_content = "(เขาอาจจะพยายามบังคับให้ลูกสาวยอมรับความชอบของตัวเอง ซึ่งเป็นเหตุผลที่ทำให้พวกเขาทะเลาะกันมาก มันเป็นความผิด แต่เป็นความผิดที่เขาทำเพราะรัก)",
