  ui_story_5079_50790700_81_dialog_content = "(บุคลิกภาพที่ดื้อดึงและความสัมพันธ์กับพ่อของเราก็ค่อนข้างคล้ายกัน...)",
  ui_story_5079_50790700_82_dialog_content = "(เธอจะเป็นฉันเองที่ถูกทำซ้ำเลียนแบบตอนเด็กหรือไม่? ไม่, นั่นไม่ได้... ฉันมั่นใจว่าฉันดูเป็นผู้ใหญ่กว่าเธอเล็กน้อย)",
