  ui_story_5079_50790700_85_dialog_content = "ฉัน... ฉันคิดว่าฉันสามารถดมกลิ่นที่มาของรสหัวหอม! มันเหมือนว่ามันเชื่อมต่อกับฉันอย่างไรสักอย่าง!",
