  ui_story_5079_50790901_62_dialog_content = "ฉ-ฉันจะทานมันในที่ที่สงบ ๆ ได้ไหม? ฉันไม่ค่อยชินกับการทานอาหารหน้าคนเยอะ ๆ แบบนี้...",
  ui_story_5079_50790901_63_dialog_content = "แน่นอนค่ะ เจ้าหญิง! แต่ถ้าข้าจะถาม ทำไมท่านดูเหมือนจะคลื่นไส้คะ?",
  ui_story_5079_50790901_64_dialog_content = "เผื่อว่าเค้กแครอทของฉันไม่ได้มาตรฐานของคุณหรือเปล่า?",
  ui_story_5079_50790901_65_dialog_content = "ไม่ นั่นไม่ใช่...",
  ui_story_5079_50790901_66_dialog_content = "ตอนนี้ที่ฉันคิดถึง มีใครเคยเห็นลูกสาวพ่อค้าแครอทกินแครอทบ้างไหม?",
  ui_story_5079_50790901_67_dialog_content = "ไม่ แต่ฉันเคยเห็นเธอทะเลาะกับพ่อครั้งหนึ่ง และดูเหมือนว่าแครอตคือสาเหตุของการทะเลาะวิวาท...",
  ui_story_5079_50790901_68_dialog_content = "?",
  ui_story_5079_50790901_69_dialog_content = "ฉัน... ฉันชอบแครอท! คุณแค่ไม่เคยเห็นฉันกินมันเท่านั้น... ด-ดูสิ? ม-มันอร่อย...",
  ui_story_5079_50790901_70_dialog_content = "อั่ก... บลือ...",
  ui_story_5079_50790901_71_dialog_content = "คุณจริงจังหยิกจมูกอยู่ใช่ไหม?",
  ui_story_5079_50790901_72_dialog_content = "ค-คุณไม่เข้าใจ! นี่คือวิธีที่ดีที่สุดในการสัมผัสรสชาติของแครอท—",
  ui_story_5079_50790901_73_dialog_content = "<size=45>พรวดดด—</size>",
  ui_story_5079_50790901_74_dialog_content = "...",
