  ui_story_5079_50790901_76_dialog_content = "...",
  ui_story_5079_50790901_77_dialog_content = "คุณไม่ชอบแครอทเลยใช่ไหม? คุณไม่ใช่เจ้าหญิงของเรา แต่คุณคือศัตรูสาบานของเรา!",
  ui_story_5079_50790901_78_dialog_content = "เพื่อนของคุณไปป่าครีมตามหาพ่อของคุณใช่ไหมครับ?",
  ui_story_5079_50790901_79_dialog_content = "เธอจะทำอะไรอยู่ที่นั้นเนี่ย? หรือว่าเธอกำลังพยายามทำลายสวรรค์ที่สวยงามและเต็มไปด้วยแครอทของเราเหรอ?",
  ui_story_5079_50790901_80_dialog_content = "เร็วเข้า! เราต้องจับโปโปแล้วบังคับให้เธอพาเราไปหาผู้หญิงคนนั้น!",
  ui_story_5079_50790901_81_dialog_content = "ไม่... ด-อย่าเข้ามาใกล้กว่านี้!",
  ui_story_5079_50790901_82_dialog_content = "คุณจะช่วยฉันใช่มั้ย? หินแห่งการล่า?",
