  ui_story_5079_50791001_1_dialog_content = "<color=#e8d9bb>ชูโอ—</color>",
  ui_story_5079_50791001_2_dialog_content = "ยินดีที่ได้พบคุณอีกครั้ง มิลาดี้ ตอนนี้เราได้มาถึงป่าครีมแล้ว กรุณาระวังขั้นบันไดเมื่อลงจากรถไฟค่ะ",
  ui_story_5079_50791001_3_dialog_content = "โอ้... เราถึงแล้วเหรอ? นั่นเร็วกว่าที่ฉันคาดไว้มาก...",
  ui_story_5079_50791001_4_dialog_content = "สภาพแวดล้อมนี่กลายเป็นเรื่องน่าเบื่ออย่างแปลกๆ ถ้าไม่มีเด็กน้อยที่น่ารำคาญหรือล้อที่ติดตัวตามมา",
  ui_story_5079_50791001_5_dialog_content = "จริง ๆ แล้วเป็นการเดินทางที่ยาวนาน แต่คุณใช้เวลาส่วนใหญ่ในการมองออกไปทางหน้าต่าง",
  ui_story_5079_50791001_6_dialog_content = "ความวุ่นวายในฟอลต้าเป็นต้นเหตุของความเครียดของคุณหรือไม่? ฉันสามารถช่วยอะไรคุณได้บ้างหรือไม่?",
  ui_story_5079_50791001_7_dialog_content = "เธอรู้ดีใช่มั้ยว่าเกิดอะไรขึ้นในเมืองนี้?",
  ui_story_5079_50791001_8_dialog_content = "ไม่ต้องคิดถึงเรื่องนั้น ฉันมีเรื่องสำคัญที่จะถาม คุณเห็นเจ้าของร้านแคร์รอตเมื่อเร็ว ๆ นี้ไหม?",
  ui_story_5079_50791001_9_dialog_content = "จากที่ฉันได้ยิน วันนี้เขาได้ออกจากเมืองด้วยรถไฟนี้เช้านี้",
  ui_story_5079_50791001_10_dialog_content = "พ่อค้าแครอตเหรอ? ใช่เลยนะ พอดีว่าเขาลงที่สถานีนี้ และฉันคิดว่าเขาพูดถึงการไปถ้ำของเทพอาหาร",
  ui_story_5079_50791001_11_dialog_content = "จริงหรือ? ดูเหมือนว่าโปโป้พูดถูกตลอดเลยนะ",
  ui_story_5079_50791001_12_dialog_content = "ฉันเชื่อว่าคุณก็มีความประทับใจเกี่ยวกับเขาเช่นกัน",
  ui_story_5079_50791001_13_dialog_content = "สุดท้ายแล้ว คุณก็ได้พบเขาตอนที่คุณเพิ่งมาถึงฟอลต้า มันเป็นการพบกันที่ค่อนข้างสนุกสนาน ฉันต้องบอกว่า",
  ui_story_5079_50791001_14_dialog_content = "ฉันได้พบเขาหรือ? คุณหมายถึงผู้โดยสารที่มีความถ่อมตัวมากๆ นั้นเป็นพ่อของโปโป่หรือ?",
  ui_story_5079_50791001_15_dialog_content = "อืม, ความยุ่งยากทั้งหมดนี้คงหลีกเลี่ยงได้ ถ้าฉันได้หยุดเขาจากการขึ้นรถไฟตอนนั้น...",
  ui_story_5079_50791001_16_dialog_content = "ดูเหมือนว่าคำถามของคุณได้รับคำตอบแล้ว โปรดจำไว้ว่าจะเอาสัมภาระของคุณเมื่อลงจากรถไฟ... เอ่อ, รอสักครู่นะครับ",
  ui_story_5079_50791001_17_dialog_content = "ขอโทษครับ แต่คุณทำลายหินแห่งการล่าไปแล้วหรือครับ?",
  ui_story_5079_50791001_18_dialog_content = "แน่นอนคุณไม่ได้ทิ้งมันไว้ที่มุมมืดของเมืองแล้วปล่อยให้มันทนทุกข์ในความโดดเดี่ยวที่น่าสะพรึงใจใช่ไหม?",
  ui_story_5079_50791001_19_dialog_content = "คุณไม่จำเป็นต้องทำให้มันดูยิ่งน่าเศร้าขนาดนั้น...",
