  ui_story_5079_50791200_14_dialog_content = "แต่น่าเสียดายที่มันไม่ช่วยอะไรฉันเท่าไหร่นัก คุณควรเก็บแรงไว้ดีกว่า—",
  ui_story_5079_50791200_15_dialog_content = "ฮ่า... เรามาถึงแล้วนะ—ถ้ำของเทพแห่งอาหาร!",
  ui_story_5079_50791200_16_dialog_content = "*แค่ก ๆ* ฉันคิดว่า... ฉันอาจจะ... แพ้แครอต...",
  ui_story_5079_50791200_17_dialog_content = "ฉันมั่นใจว่าสิ่งนี้ไม่ได้เกิดขึ้นเพราะแครอตเท่านั้น...",
  ui_story_5079_50791200_18_dialog_content = "ด้วยอิคลิพไซท์ที่รวมตัวอยู่ที่นี่เป็นจำนวนมาก ทำให้พลังความมืดเป็นพิเศษที่หนาแน่น มันเป็นเรื่องปกติที่คุณจะรู้สึกถูกส่งผลกระทบจากมัน",
  ui_story_5079_50791200_19_dialog_content = "ขอบคุณที่ถ้ำไม่ดูลึกมาก ฉันจะเข้าไปดูข้างใน ในขณะที่คุณพักผ่อนหายใจที่ทางเข้าถ้ำ",
  ui_story_5079_50791200_20_dialog_content = "หินแห่งการล่า โปรดอยู่ที่นี่และปกป้อง Popo",
  ui_story_5079_50791200_21_dialog_content = "...",
  ui_story_5079_50791200_22_dialog_content = "ทำไมเนี่ย? ฉันนึกว่าคุณสองคนเป็นเพื่อนสนิทกัน แล้วทำไมคุณถึงเป็นห่วงฉันอีกครั้งล่ะ?",
  ui_story_5079_50791200_23_dialog_content = "...",
  ui_story_5079_50791200_24_dialog_content = "หินแห่งการล่า... ฉ-ฉันคิดว่าคุณควรไปกับเธอครับ",
  ui_story_5079_50791200_25_dialog_content = "โปโป้! นี่ไม่ใช่เวลามาเล่นบทฮีโร่นะ!",
  ui_story_5079_50791200_26_dialog_content = "ฉ-ฉันไม่ใช่! ในสภาพปัจจุบัน ฉันไม่สามารถควบคุมหินแห่งการล่า... การทิ้งมันไว้กับฉันก็จะไม่มีประโยชน์",
  ui_story_5079_50791200_27_dialog_content = "อย่ากังวล ฉันรู้จักที่นี่เหมือนหน้ามือเป็นหลังมือ ถ้าอิคลิพไซท์จะหาฉันในที่ซ่อนของฉัน คงต้องใช้เวลาหลายร้อยปี! ฮีฮี...",
  ui_story_5079_50791200_28_dialog_content = "... ฉันเข้าใจคุณแล้ว คุณต้องการให้ฉันใช้หินแห่งการล่าเพื่อปกป้องพ่อของคุณถ้าเขาอยู่จริงๆ ในนั่นใช่ไหม?",
  ui_story_5079_50791200_29_dialog_content = "ไม่ต้องห่วง ฉันจะไม่ยอมให้เกิดอะไรกับเขาเลย",
  ui_story_5079_50791200_30_dialog_content = "นั่นไม่ใช่สิ่งที่ฉันหมายความเมื่อกี้... แต่...",
  ui_story_5079_50791200_31_dialog_content = "ได้โปรด... กลับมาอย่างปลอดภัยนะ ทั้งคุณและพ่อของฉัน...",
  ui_story_5079_50791200_32_dialog_content = "ความรู้สึกนั้นมาอีกครั้ง... ทำไมถ้ำนี้ถึงรู้สึกคุ้นเคยจัง?",
  ui_story_5079_50791200_33_dialog_content = "มันเหมือนกับตอนที่ฉันพบกับหัวหน้าครอบครัวเค็ชอัปและที่ปรึกษาของเธอ แต่ความรู้สึกนี้...",
  ui_story_5079_50791200_34_dialog_content = "น่าเศร้าและเจ็บปวดมาก...",
  ui_story_5079_50791200_35_dialog_content = "!",
  ui_story_5079_50791200_36_dialog_content = "ฉัน...ฉันเคยมาที่นี่มาก่อน แต่ครั้งสุดท้าย... มันเพราะฉันกำลังหนีอยู่หรือ?",
  ui_story_5079_50791200_37_dialog_content = "...",
  ui_story_5079_50791200_38_dialog_content = "...",
  ui_story_5079_50791200_39_dialog_content = "*สะอื้น* ถ้าเกิดว่า...",
  ui_story_5079_50791200_40_dialog_content = "ถ้าฉันรู้จัก Luminatics ได้เร็วกว่านี้ อาจจะ...",
