  ui_story_5079_50791200_42_dialog_content = "นอนหลับ, แพกต์",
  ui_story_5079_50791200_43_dialog_content = "แต่... แต่ฉันอยากให้แม่กอดฉันอีกครั้ง...",
  ui_story_5079_50791200_44_dialog_content = "พอแล้ว! นี่ไม่ใช่การพักผ่อน; เรากำลังวิ่งเพื่อชีวิตของเรา! Eclipsites ที่อยู่ข้างนอกนั้น—",
  ui_story_5079_50791200_45_dialog_content = "... เพื่อแม่ของเธอ เราต้องทำทุกอย่างเพื่อเอาชีวิตรอด คุณเข้าใจไหม?",
  ui_story_5079_50791200_46_dialog_content = "ฉัน... ฉันไม่อยากเข้าใจ! ฉันแค่อยากมีแม่อยู่เท่านั้น!",
  ui_story_5079_50791200_47_dialog_content = "...",
  ui_story_5079_50791200_48_dialog_content = "พ่อนี่แย่จริงๆ... เขาจะบอกฉันให้ลืมแม่ไปได้ยังไงนะ?",
  ui_story_5079_50791200_49_dialog_content = "ฉันเดินทางมาที่นี่ทั้งทาง แต่เขาก็ยังไม่มาหาฉันเลย...",
  ui_story_5079_50791200_50_dialog_content = "เขาแย่ที่สุด... ยังไงเขาถึงบอกฉันให้ลืมแม่ไปได้?",
  ui_story_5079_50791200_51_dialog_content = "ฮะ? ฉันเห็นแสงในที่นั้น...",
  ui_story_5079_50791200_52_dialog_content = "<color=#e8d9bb>*ฝีเท้า*</color>",
  ui_story_5079_50791200_53_dialog_content = "ที่นี่คือ...",
  ui_story_5079_50791200_54_dialog_content = "ไอดอล?",
  ui_story_5079_50791200_55_dialog_content = "ถ้าจริงๆ มีพระเจ้าอยู่ ขอให้ฉันได้แม่กลับมา...",
  ui_story_5079_50791200_56_dialog_content = "ไม่, รอสักครู่... แม่บอกว่าฉันต้องมีความเคารพเมื่อฉันไหว้พระ ฉันต้องทำตัวให้มีวัยให้มากขึ้นเรื่องนี้...",
  ui_story_5079_50791200_57_dialog_content = "<color=#e8d9bb>ตุ้บ—</color>",
  ui_story_5079_50791200_58_dialog_content = "ฉันปรารถนาให้การต่อสู้ทั้งหมดนี้สิ้นสุดลง ฉันปรารถนาให้มีกำลังใจในการปกป้องครอบครัวของฉัน...",
  ui_story_5079_50791200_59_dialog_content = "กรุณาทำให้ความปรารถนาของฉันเป็นจริง และฉันจะติดตามและเคารพนับถือคุณตลอดชีวิต...",
