  ui_story_5079_50791200_61_dialog_content = "<color=#e8d9bb>ในความมืดที่สงบสุข, หัวใจที่เหนื่อยล้าของเธอก็เริ่มล่องลอยเข้าสู่ห้วงลึกแห่งนิทราอย่างช้าๆ</color>",
  ui_story_5079_50791200_62_dialog_content = "<color=#e8d9bb>แคล้ง แคล้ง—</color>",
