  ui_story_5079_50791200_103_dialog_content = "!",
  ui_story_5079_50791200_104_dialog_content = "รู้สึกดีขึ้นหน่อยสิ คุณก็แค่กลับบ้านมาเท่านั้นเอง... ไม่จำเป็นต้องตื่นเต้นขนาดนั้นนะ.",
