  ui_story_5079_50791200_113_dialog_content = "!",
  ui_story_5079_50791200_114_dialog_content = "หยุดทำตัวแล้ว... คุณทำให้มันดูเหมือนการตัดสินใจที่ยากลำบาก แต่คุณไม่ได้เคลื่อนไหวเลยใช่ไหม?",
