  ui_story_5079_50791301_2_dialog_content = "เจ้าบ้านั่น มันก็ยังอยู่ที่เดิม... คงดีนะถ้ามีที่ที่เรียกว่าบ้าน",
  ui_story_5079_50791301_3_dialog_content = "ความปรารถนาของฉันจะถูกประสงค์ได้ง่าย ๆ แบบนี้เหรอ? ฉันรู้สึกว่าดีเกินไปที่จะเป็นจริง และมันทำให้ฉันรู้สึกไม่สบายใจ",
