  ui_story_5079_50791301_5_dialog_content = "อ่า แต่ไม่ว่าจะเป็นยังไงตอนนี้ก็ไม่สำคัญ! สิ่งที่สำคัญคือฉันได้ประสงค์ของฉันใช่มั้ย?",
  ui_story_5079_50791301_6_dialog_content = "...",
  ui_story_5079_50791301_7_dialog_content = "นั่นแหละ!",
  ui_story_5079_50791301_8_dialog_content = "เฮ้! คุณสบายดีไหม?",
  ui_story_5079_50791301_9_dialog_content = "อั่ก...",
  ui_story_5079_50791301_10_dialog_content = "ดี บาดเจ็บของคุณดูไม่ร้ายแรงเกินไป มานะ ลุกขึ้นมา!",
  ui_story_5079_50791301_11_dialog_content = "เฮ้ เฮ้! นี่ไม่ใช่เวลามางีบหลับนะ... ลูกสาวของคุณกำลังรอคุณอยู่ข้างนอกนะ!",
  ui_story_5079_50791301_12_dialog_content = "ม-ลูกสาวของฉัน...",
  ui_story_5079_50791301_13_dialog_content = "ถูกต้อง! คุณออกมาที่นี่เพื่อหาโพโพ้ใช่ไหม?",
  ui_story_5079_50791301_14_dialog_content = "พี-โปโป?",
  ui_story_5079_50791301_15_dialog_content = "โปโป้, นี่เป็นเธอจริง ๆ ใช่ไหม? โอ้ ขอบคุณสวรรค์... ฉันดีใจมากที่เธอปลอดภัย!",
  ui_story_5079_50791301_16_dialog_content = "ฉันผิดแล้ว โปโป... ฉันเข้มงวดกับเธอมากเกินไปแต่ก่อน ฉันจะไม่ต้องการเธอได้อย่างไรเล่า?",
  ui_story_5079_50791301_17_dialog_content = "ยากเกินไปหรือ? โอย... หัวของฉัน...",
  ui_story_5079_50791301_18_dialog_content = "ดูสิ โปโป้! นี่คือแคร์รอตที่ดีที่สุดที่ฉันเคยผลิตในชีวิต! ลูกค้าประจำของเราหนึ่งคนยืนยันว่าฉันควรจะขายมันให้เขา แต่ฉันปฏิเสธเขา...",
  ui_story_5079_50791301_19_dialog_content = "*หายใจออก* โพโพ้ยังคงไม่ยอมกินแครอทของเธอ สาวน้อยดื้อรั้นจริงๆ",
  ui_story_5079_50791301_20_dialog_content = "ฉันคิดว่าคราวนี้ฉันต้องซื้อลูกกวาดให้เธอ... แต่คราวหน้าที่เธอไม่กินอาหารฉันจะไม่ใจดีขนาดนี้แน่นอน...",
