  ui_story_5079_50791301_22_dialog_content = "ฉันไม่สามารถสอนอะไรเธอได้เลย... ฉันเป็นพ่อที่ไม่มีค่า...",
  ui_story_5079_50791301_23_dialog_content = "ถ้ามีชาวออโรเรียนชั้นสูงที่สามารถสอนเธอได้ก็จะดีนะ แต่ฉันไม่รู้จักใครที่เป็นแบบนั้นเลย...",
  ui_story_5079_50791301_24_dialog_content = "ชุดของคุณเต็มไปด้วยรูอีกแล้ว! ทำไมคุณไม่ทิ้งสิ่งที่ดูน่าเกลียดนี้ไปเลยล่ะ?",
