  ui_story_5079_50791301_30_dialog_content = "ต้องการให้ฉันยอมรับการจัดการของคุณหรือ? ไม่มีทาง! โดยเฉพาะหลังจากที่คุณบอกว่าฉันไม่มีความหวังในจดหมายของคุณ...",
