  ui_story_5079_50791301_96_dialog_content = "ฉันไม่มีเวลาเสียเปล่ากับคุณ ตอนนี้ไปให้พ้นทางฉันซะ!",
  ui_story_5079_50791401_1_dialog_content = "<color=#e8d9bb>ฟิ้วว!</color>",
  ui_story_5079_50791401_2_dialog_content = "กรร...",
  ui_story_5079_50791401_3_dialog_content = "นั่นคือตัวสุดท้ายแล้ว เราควรจะ—",
  ui_story_5079_50791401_4_dialog_content = "...",
  ui_story_5079_50791401_5_dialog_content = "เฮ้! เราไม่รู้ว่ามีอะไรรออยู่ข้างหน้า! คุณใช้ Luminatics ไม่ได้ ดังนั้นอยู่ข้างหลังฉัน!",
  ui_story_5079_50791401_6_dialog_content = "โปโป! โปโป, คุณอยู่ที่ไหน?",
  ui_story_5079_50791401_7_dialog_content = "จุ๊จุ๊... เขาไม่ฟังเลยเหมือนโปโป้ คงจริงที่ว่าพวกเขาคล้ายกันจริง ๆ...",
  ui_story_5079_50791401_8_dialog_content = "<size=45>โปโป—</size>",
  ui_story_5079_50791401_9_dialog_content = "ฮะ? นี่ตะกี๊ได้ยินเสียงพ่อรึเปล่า?",
  ui_story_5079_50791401_10_dialog_content = "<size=45>พ่อ! ลูกอยู่ที่นี่ค่ะ!</size>",
  ui_story_5079_50791401_11_dialog_content = "อยู่ตรงนั้นสิ โปโป้! ฉันกำลังจะไปหาคุณ!",
  ui_story_5079_50791401_12_dialog_content = "หยุด! ฉันได้ยินเสียงบางอย่างเคลื่อนไหว...",
  ui_story_5079_50791401_13_dialog_content = "แก๊ก... แกล๊ก แกล๊ก แกล๊ก—",
  ui_story_5079_50791401_14_dialog_content = "ตูม!",
  ui_story_5079_50791401_15_dialog_content = "ปอ...",
  ui_story_5079_50791401_16_dialog_content = "โปโปโป!",
  ui_story_5079_50791401_17_dialog_content = "กะแล้วเชียว! สัตว์ประหลาดแครอทปลอมตัวเป็นไอดอลที่อยู่ข้างนอก!",
  ui_story_5079_50791401_18_dialog_content = "สวะไร้เกียรติ... มันได้แกล้งทำตัวเป็นเทพแห่งอาหารและเอาของสักการะของคนอื่นมาเป็นของตัวเอง!",
  ui_story_5079_50791401_19_dialog_content = "โป... โปโป!",
  ui_story_5079_50791401_20_dialog_content = "รอสักครู่ มันกำลังไปที่ไหน? เฮ้! ฝ่ายตรงข้ามของคุณอยู่ที่นี่นะ!",
  ui_story_5079_50791401_21_dialog_content = "<color=#e8d9bb>ฟิ้ว—</color>",
  ui_story_5079_50791401_22_dialog_content = "มันเพิกเฉยต่อการโจมตีของฉันเลย! นี่! หยุดนะ!",
  ui_story_5079_50791401_23_dialog_content = "โปโปโป!",
  ui_story_5079_50791401_24_dialog_content = "S-อยู่กลับ... อย่าเข้ามานะ!",
  ui_story_5079_50791401_25_dialog_content = "ร-รับนี่ไป!",
  ui_story_5079_50791401_26_dialog_content = "<color=#e8d9bb>ผัวะ—</color>",
  ui_story_5079_50791401_27_dialog_content = "ปอ? ป๊อป๊อป๊อ...",
  ui_story_5079_50791401_28_dialog_content = "พลังลูมินาติกส์ของโปโป... ฉันไม่เชื่อว่าฉันจะได้เห็นพลังของลูกสาวของฉันด้วยตัวเอง...",
  ui_story_5079_50791401_29_dialog_content = "นี่จะเป็นเวลาที่จะยืนอยู่ในความทึ่งใจหรือ? ไปหาที่ปลอดภัยซ่อนตัวซะ!",
  ui_story_5079_50791401_30_dialog_content = "แต่ลูกสาวของฉัน...",
  ui_story_5079_50791401_31_dialog_content = "เดี๋ยวฉันดูแลเธอเอง!",
  ui_story_5079_50791401_32_dialog_content = "<color=#e8d9bb>ฟิ้ว—</color>",
  ui_story_5079_50791401_33_dialog_content = "Popopo... การโจมตีของคุณไม่มีผลต่อฉันเลย! ฉันไม่สนใจคุณ...",
  ui_story_5079_50791401_34_dialog_content = "...",
  ui_story_5079_50791401_35_dialog_content = "แต่คุณโปโป... แม้จะมีชื่อที่น่าตื่นตาตื่นใจแบบนี้ คุณก็ยังเกลียดแครอท!",
  ui_story_5079_50791401_36_dialog_content = "ความเกลียดชังของคุณต่อพวกเขาเป็นเชื้อเพลิงของพลังของฉัน!",
  ui_story_5079_50791401_37_dialog_content = "ฉันคิดถูกเลย สิ่งนี้จริง ๆ แล้วตามหาโปโป้!",
  ui_story_5079_50791401_38_dialog_content = "หินแห่งการล่า! ไม่, รอสักครู่, มันไม่ใช่—",
  ui_story_5079_50791401_39_dialog_content = "โปโปโป! คุณหมายถึงนี่รึเปล่า?",
  ui_story_5079_50791401_40_dialog_content = "!",
  ui_story_5079_50791401_41_dialog_content = "หินแห่งการล่า... คืนมันให้ฉันสิ!",
  ui_story_5079_50791401_42_dialog_content = "ล้อไร้ประโยชน์ของเธอ! จะยอมให้ตัวประหลาดนี้ใช้เธอแบบนั้นจริงๆหรือ? มาที่นี่ทันที...",
  ui_story_5079_50791401_43_dialog_content = "อั่ก...",
  ui_story_5079_50791401_44_dialog_content = "โปโปโป!",
  ui_story_5079_50791401_45_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5079_50791401_46_dialog_content = "หินแห่งการล่า... มันไม่ฟังฉันแล้วเหรอ?",
  ui_story_5079_50791401_47_dialog_content = "ฉันขอบคุณมากสำหรับอาวุธที่คุณให้ฉัน",
  ui_story_5079_50791401_48_dialog_content = "แต่ที่สำคัญที่สุด ฉันขอบคุณคุณมาก ๆ นะ โพโพ...",
  ui_story_5079_50791401_49_dialog_content = "ทั้งหมดที่ฉันต้องการคืออีกคำเดียว คำสุดท้ายที่อร่อยที่สุดของความเกลียดชัง แล้วฉันจะสามารถครอบครองทุกชิ้นอาหารในโลกนี้ได้!",
  ui_story_5079_50791401_50_dialog_content = "เร็ว ๆ นี้ฉันจะมอบความอร่อยที่กรอบและน่าต้านทานของแครอทไม่เพียงแค่ให้กับโฟลต้าเท่านั้น แต่ทั้งหมดของแอสตรา!",
  ui_story_5079_50791401_51_dialog_content = "โปโปโป!",
  ui_story_5079_50791401_52_dialog_content = "ไม่... คุณทำไม่ได้! โลกไม่สามารถจบลงแบบนั้นได้...",
  ui_story_5079_50791401_53_dialog_content = "\"ฉันทำไม่ได้\" คุณพูดอย่างนั้นเหรอ? โปโปโป... ฉันไม่เห็นด้วยนะ! สุดท้ายแล้ว ฉันก็ไม่คิดว่าจะมีพลังมากขนาดนี้ ถ้าคุณไม่ทิ้งฉันไว้ที่นี่!",
  ui_story_5079_50791401_54_dialog_content = "ปอ... ปอ...",
  ui_story_5079_50791401_55_dialog_content = "ยังไง... ยังไงคุณจึงทิ้งแคร์รอตน้อยน่ารักอยู่คนเดียวที่นี่ได้?",
  ui_story_5079_50791401_56_dialog_content = "มันมืด...มืดมาก...ไม่มีสารอาหาร...ไม่มีแรง...",
  ui_story_5079_50791401_57_dialog_content = "เทพอาหารทั้งหลาย ฉันปรารถนาอยู่ในโลกที่ไม่มีแครอท!",
  ui_story_5079_50791401_58_dialog_content = "ทำไมเราถึงต้องกินอะไรที่น่ารังเกียจจนไม่ควรจะมีอยู่เลยล่ะครับ?",
  ui_story_5079_50791401_59_dialog_content = "ฉันขอร้องคุณ! โปรดลบแครอทออกจากสูตรอาหารทุกสูตรที่โลกรู้จัก!",
  ui_story_5079_50791401_60_dialog_content = "ฉัน...ไม่ควรเคย...ปรากฏตัวในโลกนี้...",
  ui_story_5079_50791401_61_dialog_content = "ถูกเกลียดชัง, ถูกทอดทิ้ง, ไม่มีความจำเป็น...",
  ui_story_5079_50791401_62_dialog_content = "โอ้เทพแห่งอาหารที่ยิ่งใหญ่ โปรดอวยพรความสงบสุขและความปลอดภัยให้กับครอบครัวของเรา...",
  ui_story_5079_50791401_63_dialog_content = "ฟังของขวัญของฉันด้วยเถิด เทพแห่งอาหารที่ใจดี! โปรดทำให้เด็กสาวคนนั้นตกหลุมรักฉัน!",
  ui_story_5079_50791401_64_dialog_content = "โปรดรับเครื่องสังเวยของฉัน, เทพแห่งอาหาร...",
  ui_story_5079_50791401_65_dialog_content = "เทพอาหาร เทพอาหาร... มันแค่รูปปั้นใช่ไหม? ทำไมทุกคนถึงต้องขอให้มันประสงค์ให้ความปรารถนาเป็นจริง?",
  ui_story_5079_50791401_66_dialog_content = "พวกเขาสวดภาวนาและขอร้อง แต่ไม่มีอะไรเกิดขึ้นเลย... มันไม่คู่ควรได้รับการสักการะ...",
  ui_story_5079_50791401_67_dialog_content = "แต่ฉันทำ... เพราะฉันเป็นตัวจริง! ฉันยังมีชีวิตอยู่!",
  ui_story_5079_50791401_68_dialog_content = "สังเกตฉันสิ! มองฉันสิ! ชื่นชมฉันสิ! ฉันดีกว่ารูปปั้นนั้น... เพราะฉันสามารถทำให้ความฝันของคุณเป็นจริง!",
  ui_story_5079_50791401_69_dialog_content = "...",
  ui_story_5079_50791401_70_dialog_content = "โปโปโป!",
  ui_story_5079_50791401_71_dialog_content = "อีกทั้ง เทพแห่งอาหารจะไม่เคยตอบสนองคำอธิษฐานของคุณ และแทนที่พระองค์—",
  ui_story_5079_50791401_72_dialog_content = "ฉันจะสนุกกับของที่คุณให้เอ็นดูอย่างดี!",
  ui_story_5079_50791401_73_dialog_content = "โอ้ พระเจ้าแห่งอาหาร โปรดรับแครอทนี้เป็นของถวายจากฉัน ลองชิมดูสิ คุณจะรู้เลยว่าทำไมฉันถึงเกลียดมันขนาดนี้",
  ui_story_5079_50791401_74_dialog_content = "ใช่ โปโป... จงเกลียดพวกเขาต่อไป! จงเกลียดฉันต่อไป! มันทำให้ฉันแข็งแกร่งขึ้นเท่านั้น!",
  ui_story_5079_50791401_75_dialog_content = "โอ้เทพแห่งอาหาร คุณสามารถทำให้สามีที่น่ารำคาญของฉันหายไปได้หรือไม่?",
  ui_story_5079_50791401_76_dialog_content = "ใช่ ใช่! ข้ายินดีที่จะประทานความปรารถนาที่เต็มไปด้วยความเกลียดชังและอร่อยน่ากินแบบนี้!",
  ui_story_5079_50791401_77_dialog_content = "... กรุณารับความยินดีอันยิ่งใหญ่นี้เป็นการแลกเปลี่ยนเพื่อการค้นหาลูกสาวของฉัน...",
  ui_story_5079_50791401_78_dialog_content = "ใช่... ใช่ค่ะ! คุณมีความคิดเบื้องต้นว่าฉันรอช่วงเวลานี้มานานแค่ไหนหรือไม่?",
  ui_story_5079_50791401_79_dialog_content = "... อืม?",
  ui_story_5079_50791401_80_dialog_content = "โป... โปโปโป!",
  ui_story_5079_50791401_81_dialog_content = "...",
  ui_story_5079_50791401_82_dialog_content = "ดังนั้นทุกอย่างนี้เกิดขึ้นเพราะฉันเหรอ?",
  ui_story_5079_50791401_83_dialog_content = "ตัวปีศาจแคร์รอตนี้... มันคือแคร์รอตที่ฉันทิ้งไว้ที่นี่นานแล้ว.",
  ui_story_5079_50791401_84_dialog_content = "แน่นอน และตอนนี้ถึงเวลาที่จะตอบแทนคุณเต็มที่แล้ว!",
  ui_story_5079_50791401_85_dialog_content = "อ๊าาา—",
  ui_story_5079_50791401_86_dialog_content = "โปโป้!",
  ui_story_5079_50791401_87_dialog_content = "สัตว์ประหลาดแครอทกำลังใช้พลังของหินแห่งการล่าเพื่อทำให้หนามขึ้นบนเถาของมัน!",
  ui_story_5079_50791401_88_dialog_content = "เฮ้อ... ถ้าหินแห่งการล่าไม่ได้กลายเป็นอาวุธของมัน แครอทโง่ ๆ นั่นคงไม่มีวันแรงขนาดนี้!",
  ui_story_5079_50791401_89_dialog_content = "นี่ไม่ใช่เวลาที่คุณจะทำให้สถานการณ์ยากขึ้นอีกสำหรับฉันนะ คนเลว!",
  ui_story_5079_50791401_90_dialog_content = "ปล่อย... ปล่อยลูกสาวฉันเถอะ!",
  ui_story_5079_50791401_91_dialog_content = "ห๊ะ",
  ui_story_5079_50791401_92_dialog_content = "รอสักครู่, คุณคิดว่าคุณกำลังทำอะไรอยู่หรือ? คุณยังไม่สามารถใช้ Luminatics...",
  ui_story_5079_50791401_93_dialog_content = "ถ้าฉันใช้ลูมินาติกส์ไม่ได้ ฉันจะใช้ไม้และหินมาต่อสู้",
  ui_story_5079_50791401_94_dialog_content = "แม้ไม่มีอะไรเลย ฉันก็ยังมีหมัดของฉัน!",
  ui_story_5079_50791401_95_dialog_content = "คุณแค่อยากถูกฆ่าเท่านั้นเอง!",
  ui_story_5079_50791401_96_dialog_content = "* coughs * สัตว์ประหลาดนั่นมีสาวน้อยของฉันอยู่ แม้ว่าจะต้องสละชีวิตฉันก็ต้องช่วยเธอ!",
  ui_story_5079_50791401_97_dialog_content = "ปล่อยเธอไป!",
  ui_story_5079_50791401_98_dialog_content = "ฉันบอกให้เธอทิ้งเธอให้ฉันดูแล... อืม...",
  ui_story_5079_50791401_99_dialog_content = "หัวของฉัน... ทำไมสิ่งนี้ต้องเกิดขึ้นตอนนี้...",
  ui_story_5079_50791401_100_dialog_content = "นี่ใครเนี่ย? อยู่ห่างจากลูกสาวฉัน!",
  ui_story_5079_50791401_101_dialog_content = "ปล่อยเธอไปเดี๋ยวนี้ ไม่งั้นคุณจะเสียใจนะ!",
  ui_story_5079_50791401_102_dialog_content = "หนีจากเธอเดี๋ยวนี้ ไม่งั้นคุณจะเสียใจ!",
  ui_story_5079_50791401_103_dialog_content = "หยุด, ให้ฉัน...",
  ui_story_5079_50791401_104_dialog_content = "โปโปโป!",
  ui_story_5079_50791401_105_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5079_50791401_106_dialog_content = "อืม... แค่นี้เองเหรอที่คุณมี? มาสู้กับฉันสิ, อสุรกาย!",
  ui_story_5079_50791401_107_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5079_50791401_108_dialog_content = "ฉันยังไม่จบเรื่องหรอกนะ... ปล่อยเธอไปสิ!",
  ui_story_5079_50791401_109_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5079_50791401_110_dialog_content = "นี่... มันยังไม่จบหรอก...",
  ui_story_5079_50791401_111_dialog_content = "รีบนะ โพโพ... ฉันจะดึงหนามออกให้เธอ...",
  ui_story_5079_50791401_112_dialog_content = "<color=#e8d9bb>แทง—</color>",
  ui_story_5079_50791401_113_dialog_content = "พ่อ... มือของคุณเลือดออกมากเกินไป! ถ้าแบบนี้คุณจะ—",
  ui_story_5079_50791401_114_dialog_content = "อย่าห่วงเรื่องฉัน! ไปเถอะพ่อ! นี่... เป็นความผิดของฉันทั้งหมดอยู่แล้ว...",
  ui_story_5079_50791401_115_dialog_content = "นั่นเป็นเหตุผลที่ฉันควรจะ—",
  ui_story_5079_50791401_116_dialog_content = "พอกันที! ฉันคือคนที่ซื้อของถวายที่ถูกสาปนั้น... ถ้าฉันเข้าใจมากขึ้นเพียงใด...",
  ui_story_5079_50791401_117_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5079_50791401_118_dialog_content = "เออ... ในที่สุดก็ปล่อย? ร-รีบนะ โพโพ...",
  ui_story_5079_50791401_119_dialog_content = "พ่อ...",
  ui_story_5079_50791401_120_dialog_content = "ฉันต้องการให้คุณหันกลับไปและเดินไปทางทางเข้าถ้ำ... อย่ากลัว และอย่าหันหลังกลับมาดู...",
  ui_story_5079_50791401_121_dialog_content = "แพกต์, ฉันต้องการให้คุณเดินมาทางฉันอย่างช้า ๆ ไม่ต้องกลัว, และอย่าหันหลัง...",
  ui_story_5079_50791401_122_dialog_content = "ร-รีบเข้า...",
  ui_story_5079_50791401_123_dialog_content = "ท-ท่านพ่อ?",
  ui_story_5079_50791401_124_dialog_content = "ครั้งนี้ ฉันไม่ได้สวดภาวนาให้กับใครหรืออะไรเลย...",
  ui_story_5079_50791401_125_dialog_content = "ฉันจะช่วยครอบครัวของฉันด้วยมือของฉันเอง!",
  ui_story_5079_50791501_1_dialog_content = "<color=#e8d9bb>ฟิ้วว!</color>",
  ui_story_5079_50791501_2_dialog_content = "ปอ...",
  ui_story_5079_50791501_3_dialog_content = "*หอบ* ในที่สุด...",
  ui_story_5079_50791501_4_dialog_content = "พอโพโพ่ยังขยับตัวได้มั้ยนะ? คุณต้อง...รีบ...",
  ui_story_5079_50791501_5_dialog_content = "มอนสเตอร์แครอตกำลังตามหาคุณ ถ้ามันสามารถดูดซับความเกลียดชังของคุณได้ เราจะไม่มีโอกาสต่อสู้กับมัน...",
  ui_story_5079_50791501_6_dialog_content = "แต่...แต่พ่อผม, เขา...",
  ui_story_5079_50791501_7_dialog_content = "ฉันจะพาพ่อของคุณมาหาคุณหลังจากที่ฉันเอาชนะสิ่งนั้น",
  ui_story_5079_50791501_8_dialog_content = "แต่ตอนนี้คุณต้องออกจากที่นี่ รู้ไหม? นี่จะเป็นความท้าทายที่ยิ่งใหญ่ที่สุดของคุณเลย!",
  ui_story_5079_50791501_9_dialog_content = "ฉัน... ฉันทำได้!",
  ui_story_5079_50791501_10_dialog_content = "ไม่! ไม่มีทางหนีฉันหรอก!",
  ui_story_5079_50791501_11_dialog_content = "คู่ต่อสู้ของแกอยู่ที่นี่!",
  ui_story_5079_50791501_12_dialog_content = "<color=#e8d9bb>ฟิ้วว!</color>",
  ui_story_5079_50791501_13_dialog_content = "ปอ...",
  ui_story_5079_50791501_14_dialog_content = "ชิ, ยังไม่มีความเสียหายเลยหรอ? รู้สึกเหมือนว่า...",
  ui_story_5079_50791501_15_dialog_content = "โพโพโพ... รู้สึกเหมือนขาดอะไรไป ใช่ไหม?",
  ui_story_5079_50791501_16_dialog_content = "ถ้าฉันไม่ผิด, คุณใช้พลังเกือบหมดไปแล้วใช่ไหม?",
  ui_story_5079_50791501_17_dialog_content = "คุณจะทำอะไรได้บ้างถ้าไม่มีอาวุธนี้?",
  ui_story_5079_50791501_18_dialog_content = "เฮ้อ... อย่าดูถูกข้านะ เจ้าสัตว์ประหลาด!",
  ui_story_5079_50791501_19_dialog_content = "<color=#e8d9bb>ฟิ้วว! กรี๊ด—</color>",
  ui_story_5079_50791501_20_dialog_content = "...",
  ui_story_5079_50791501_21_dialog_content = "ถึงขีดจำกัดแล้วเหรอ? น่าผิดหวังจริง ๆ!",
  ui_story_5079_50791501_22_dialog_content = "ด้วยอาวุธที่คุณให้ฉัน... ฉันกำลังเริ่มต้นเท่านั้นเอง!",
  ui_story_5079_50791501_23_dialog_content = "อั่ก!",
  ui_story_5079_50791501_24_dialog_content = "เลยนี่คือพลังของหินแห่งการล่า... ฮ่า, นี่คือครั้งแรกของฉัน... ที่ได้สัมผัสมันด้วยตัวเอง...",
  ui_story_5079_50791501_25_dialog_content = "ฉันคิดว่าฉันควรจะพิสูจน์พลังของฉันให้คุณเห็นด้วย...",
  ui_story_5079_50791501_26_dialog_content = "<color=#e8d9bb>ฟิ้วว! กรี๊ด—</color>",
  ui_story_5079_50791501_27_dialog_content = "* coughs * คุณวันนี้ไม่ทำใจให้ฉันเลยใช่มั้ย?",
  ui_story_5079_50791501_28_dialog_content = "นี่คือความเคียดแค้นที่คุณรู้สึกต่อฉันหรือเปล่า หินแห่งการล่า? ฮ่าๆ...",
  ui_story_5079_50791501_29_dialog_content = "ฉันคิดว่าฉันสมควรได้รับมัน",
  ui_story_5079_50791501_30_dialog_content = "ฉันคิดว่าคุณปฏิเสธที่จะมากับฉัน แต่คุณถูกควบคุมโดยสัตว์ประหลาดตัวนี้ที่มีรูปร่างเหมือนแครอทตลอดเวลา...",
  ui_story_5079_50791501_31_dialog_content = "คุณช่วยฉันมาตลอดเวลา แต่ฉันได้รับความกรุณาของคุณเป็นเรื่องแน่นอนและบ่นอย่างต่อเนื่องเกี่ยวกับการกำจัดคุณ...",
  ui_story_5079_50791501_32_dialog_content = "ฉันไม่หยุดบอกตัวเองว่านี่คือสิ่งที่ฉันต้องการ... ฉันจับตัวเองอยู่ในความโกหกที่ดื้อรั้น",
  ui_story_5079_50791501_33_dialog_content = "และเพราะสาเหตุนั้น... ฉันได้ส่งมอบคุณให้กับศัตรู",
  ui_story_5079_50791501_34_dialog_content = "<color=#e8d9bb>ฟิ้วว! กรี๊ด—</color>",
  ui_story_5079_50791501_35_dialog_content = "Tsk, ฉันไม่รู้จะทำอะไรต่อไปแล้ว...",
  ui_story_5079_50791501_36_dialog_content = "โปโปโป! รู้สึกถึงความแรงของหนวดที่ได้รับพลังของฉันซะ!",
  ui_story_5079_50791501_37_dialog_content = "อ๊ากกกก!",
  ui_story_5079_50791501_38_dialog_content = "...",
  ui_story_5079_50791501_39_dialog_content = "อึก... ฉันยังสบายดี สุดท้ายแล้ว นี่ไม่ใช่ครั้งแรก... ที่ฉันโดนมัดโดยหินแห่งการล่า",
  ui_story_5079_50791501_40_dialog_content = "ดีใจที่โปโป้ไม่ได้อยู่ที่นี่เห็นสิ่งนี้ ไม่งั้นเธอคงด่าฉันมากขึ้นอีก...",
  ui_story_5079_50791501_41_dialog_content = "เขาก็ไม่อยู่ที่นี่เพื่อมาช่วยฉันในครั้งนี้เหมือนกัน...",
  ui_story_5079_50791501_42_dialog_content = "คนเดียวที่ช่วยฉันได้ตอนนี้...",
  ui_story_5079_50791501_43_dialog_content = "...",
  ui_story_5079_50791501_44_dialog_content = "ทุกอย่างนี้รู้สึกคุ้นเคยมาก...",
  ui_story_5079_50791501_45_dialog_content = "...อ๊าก",
  ui_story_5079_50791501_46_dialog_content = "ใช่ ต่อสู้และทนทุกข์... มันจะทำให้เงื่อนงำของคุณแน่นขึ้นอย่างเดียว!",
  ui_story_5079_50791501_47_dialog_content = "ฉัน... ฉันไม่ต้องการให้คุณบอกฉันว่า... แต่...",
  ui_story_5079_50791501_48_dialog_content = "ฉ-ฉันไม่อยากจะแพ้... หินแห่งการล่า",
  ui_story_5079_50791501_49_dialog_content = "ฉันไม่อยากจะแพ้... สิทธิ์ที่จะมีเธออยู่ข้างฉัน...",
  ui_story_5079_50791501_50_dialog_content = "...",
  ui_story_5079_50791501_51_dialog_content = "คุณไม่คิดถึงการพลิกตัวบนหน้าฉันตอนที่ฉันหลับหรือเปล่า?",
  ui_story_5079_50791501_52_dialog_content = "หรือกำลังทำให้ผู้คนกลัวในเวลาที่แย่ที่สุดหรือ?",
  ui_story_5079_50791501_53_dialog_content = "คุณไม่คิดถึงการที่โดนเข็มเจาะเสื้อผ้าของฉันโดยไม่ได้ตั้งใจหรือแม้กระทั่งทำมันโดยตั้งใจหรือเปล่า?",
  ui_story_5079_50791501_55_dialog_content = "...",
  ui_story_5079_50791501_56_dialog_content = "ฉัน... เป็นส่วนหนึ่ง... ของแพกต์...",
  ui_story_5079_50791501_57_dialog_content = "แต่... ขอร้อง... จำไว้...",
  ui_story_5079_50791501_58_dialog_content = "พลังของฉัน... มาจากทั้งหมด...",
  ui_story_5079_50791501_59_dialog_content = "จาก...คุณ!",
  ui_story_5079_50791501_60_dialog_content = "หินแห่งการล่า... คุณจริง ๆ แล้วพูดได้เหรอครับ?",
  ui_story_5079_50791501_61_dialog_content = "ภาพที่ฉันเห็นนี้คืออะไร?",
  ui_story_5079_50791501_62_dialog_content = "นี่คือ... ความทรงจำแรกๆ ของฉันกับหินแห่งการล่าเหรอครับ?",
  ui_story_5079_50791501_63_dialog_content = "โอ๊ย... พลังนี้... เจ็บชะมัดเลย...",
  ui_story_5079_50791501_64_dialog_content = "ไม่... ไม่ใช่แบบนี้! ฉันต้องการใช้พลังของฉันเพื่อสู้กับอิคลิพไซท์...",
  ui_story_5079_50791501_65_dialog_content = "อย่าให้สูญเสียการควบคุมในที่นี้...",
  ui_story_5079_50791501_66_dialog_content = "แคล้ง แคล้ง...",
  ui_story_5079_50791501_67_dialog_content = "หา? พลังของฉัน... ทำลายเทวรูปนั้นได้เหรอ?",
  ui_story_5079_50791501_68_dialog_content = "ไม่... มันยังอยู่ที่นั่น แต่คุณ... มันทิ้งคุณไว้หรือ?",
  ui_story_5079_50791501_69_dialog_content = "เหมือนกับที่เทพเจ้าทอดทิ้งพวกเราไว้ที่เมืองเก่าและปล่อยให้พวกเราตายในมือของอิคลิพไซท์...",
  ui_story_5079_50791501_70_dialog_content = "ฉันสูญเสียแม่และบ้านเกิด... สำหรับทุกสิ่งที่เรารู้ พ่อและฉันอาจจะถูกพวกอิคลิพไซท์ฉีกขาดในวันพรุ่งนี้",
  ui_story_5079_50791501_71_dialog_content = "และคุณ... คุณต้องใช้ชีวิตที่เหลืออยู่บนพื้นที่เย็นชา มองไปที่รูปปั้นที่เคยเป็นของคุณ...",
  ui_story_5079_50791501_72_dialog_content = "มันเจ็บมั้ย? คุณบอกฉันได้มั้ย... ทำไมเราต้องทนความเจ็บปวดแบบนี้?",
  ui_story_5079_50791501_73_dialog_content = "ไม่... ไม่ใช่แบบนั้น...",
  ui_story_5079_50791501_74_dialog_content = "คุณกับฉัน... เราไม่เหมือนกัน... ดังนั้นหยุดทำตัวเศร้าสมเพชเถอะ",
  ui_story_5079_50791501_75_dialog_content = "รูปปั้นของคุณอยู่ที่นั่น ดังนั้นคุณยังมีที่ที่เรียกว่าบ้าน... ไม่เป็นไร ใช้พลังของฉันเพื่อกลับไปยังที่ที่คุณควรอยู่...",
  ui_story_5079_50791501_76_dialog_content = "<color=#e8d9bb>เด็กหญิงเก็บชิ้นส่วนที่แตกของรูปปั้นเหมือนกับว่ามันคือเปลวไฟสุดท้ายในโลกแห่งความมืดที่ไม่มีวันสิ้นสุด</color>",
  ui_story_5079_50791501_77_dialog_content = "<color=#e8d9bb>ด้วยความปรารถนาที่เล็กน้อยแต่เต็มไปด้วยความเชื่อถือตนเอง, เธอใส่แรงใจทั้งหมดเข้าไป...</color>",
  ui_story_5079_50791501_78_dialog_content = "...",
  ui_story_5079_50791501_79_dialog_content = "ตอนนี้ไปเถอะ กลับบ้าน...",
  ui_story_5079_50791501_80_dialog_content = "...",
  ui_story_5079_50791501_81_dialog_content = "คุณกำลังพูดว่า... คุณอยากอยู่กับฉันเหรอ? คุณจะ... ทำแบบนั้นจริง ๆ หรือ?",
  ui_story_5079_50791501_82_dialog_content = "พลังของฉัน... ตอนนี้รู้สึกสงบขึ้นมาก คุณช่วยฉันแบกรับภาระส่วนใหญ่หรือเปล่า?",
  ui_story_5079_50791501_83_dialog_content = "ฉันรู้สึกอบอุ่นและสบายใจมากเลยตอนนี้... ขอบคุณนะ... ขอบคุณมากๆ...",
  ui_story_5079_50791501_84_dialog_content = "ฉัน... ฉันคือคนที่ขอให้หินแห่งการล่าอยู่ด้วยกับฉันเหรอ?",
  ui_story_5079_50791501_85_dialog_content = "ฉันคือผู้ที่ได้ให้พลังของฉันให้มัน...",
  ui_story_5079_50791501_86_dialog_content = "ใช่... พลังนี้... ทั้งหมดเป็นของคุณ",
  ui_story_5079_50791501_87_dialog_content = "คุณกลัวที่จะทำให้พ่อของคุณผิดหวัง... ดังนั้นคุณจึงปฏิเสธที่จะเชื่อมั่นในความแข็งแกร่งของตัวเอง.",
  ui_story_5079_50791501_88_dialog_content = "ด้วยเหตุผลนั้น คุณทำให้ตัวเองเชื่อว่าพลังนี้มาจากฉัน...",
  ui_story_5079_50791501_89_dialog_content = "ฉันไม่ได้อ่อนแอเท่าที่คุณคิด... ฉันแค่ลืมเท่านั้นเอง.",
  ui_story_5079_50791501_90_dialog_content = "อาจจะเป็นอย่างนั้น แต่ที่ไหนสักแห่งลึกๆ ในหัวใจของคุณ คุณยังคงจำเสมอ",
  ui_story_5079_50791501_91_dialog_content = "ไม่ใช่ว่าคุณไม่มั่นใจในความสามารถของตัวเอง แต่คุณเพียงแค่ต้องการให้มีใครสักคนอยู่เคียงข้างคุณไม่ว่าสถานการณ์จะเป็นอย่างไร...",
  ui_story_5079_50791501_92_dialog_content = "ดังนั้นฉันก็ทำตามนั้น ฉันเป็นเพื่อนที่เงียบๆของคุณ - หรืออย่างน้อยฉันก็อยากให้คุณรู้สึกเช่นนั้นเกี่ยวกับฉัน",
  ui_story_5079_50791501_93_dialog_content = "คู่ครองที่เงียบ ๆ ก็ควรพูดขึ้นเมื่อสถานการณ์ต้องการ",
  ui_story_5079_50791501_94_dialog_content = "ฉันหวังว่าคุณคงบอกฉันแต่แรกว่าคุณสามารถพูดได้. ฉัน...",
  ui_story_5079_50791501_95_dialog_content = "ฉันอาจจะไม่ใช่คนที่ตรงไปตรงมาเวลาเรื่องแบบนี้... แต่ฉันยังอยากรู้ว่าเธอรู้สึกยังไงบ้างเนาะ!",
  ui_story_5079_50791501_96_dialog_content = "เพราะคุณซื่อสัตย์มากเมื่อกี้ ทำให้ฉันตัดสินใจพูด...",
  ui_story_5079_50791501_97_dialog_content = "ฉันยังจำได้ถึงความใจดีที่เธอทำให้ฉันในคืนนั้น... ฉันรอเวลาที่เธอสามารถยอมรับฉันได้ในที่สุด",
  ui_story_5079_50791501_98_dialog_content = "นั่นเป็นเหตุผลที่ฉันสามารถยืนอยู่ข้างๆ คุณและช่วยคุณอีกครั้ง!",
  ui_story_5079_50791501_99_dialog_content = "เรื่องพลังของคุณ ฉันจะคืนทั้งหมดให้คุณ!",
  ui_story_5079_50791501_100_dialog_content = "ฉันรู้จักความแข็งแกร่งและความใจดีของคุณมากกว่าใคร แพกต์",
  ui_story_5079_50791501_101_dialog_content = "ตอนนี้เอาชนะความเจ็บปวดจากอดีตของคุณและทำลายปีศาจแครอทนั้น!",
  ui_story_5079_50791501_102_dialog_content = "ฮัมฟ์, คุณไม่จำเป็นต้องคืนมันให้ฉัน...",
  ui_story_5079_50791501_103_dialog_content = "สุดท้ายแล้ว มันก็คือ<color=#FFB400>เรา</color>ตลอดเวลานี้ทั้งหมด ไม่ใช่เหรอ?",
  ui_story_5079_50791501_104_dialog_content = "<color=#e8d9bb>ฟิ้ว! แตก!</color>",
  ui_story_5079_50791501_105_dialog_content = "หืม, การมัดเชือกแบบนี้เพียงเท่ากับการเล่นของเด็กเท่านั้น ถ้าเทียบกับสิ่งที่พวกเราสามารถทำได้จริง ๆ!",
  ui_story_5079_50791501_106_dialog_content = "ทำไมอาวุธนี้ถึงไม่เชื่อฟังฉันล่ะ?",
  ui_story_5079_50791501_107_dialog_content = "ฉันยังอยากลิ้มรสความทุกข์ของคุณอีกหน่อย...",
  ui_story_5079_50791501_108_dialog_content = "แต่ดูเหมือน... เวลาของเราหมดแล้ว กระจายไปทั่ว กลิ่นหอมแครอทอร่อยๆ ของฉัน!",
  ui_story_5079_50791501_109_dialog_content = "กราาาาาา—",
  ui_story_5079_50791501_110_dialog_content = "เป็นตลกจริง คิดว่าเจ้าน้อยๆเหล่านี้จะหยุดฉันได้เหรอ? ฮ่า... นั่นหมายความว่าเธอก็ไม่แรงกว่าพวกเขาเลยสินะ?",
  ui_story_5079_50791501_111_dialog_content = "ลูกปลาเล็กๆ ลูกปลาเล็กๆ!",
  ui_story_5079_50791501_112_dialog_content = "ง-ความเงียบ!",
  ui_story_5079_50791501_113_dialog_content = "ตราบใดที่สิ่งนี้อยู่ในการควบคุมของฉัน คุณไม่มีอำนาจที่นี่!",
  ui_story_5079_50791501_114_dialog_content = "ฉัน, ในทางกลับกัน, แค่ต้องการดื่มความเกลียดชังของโปโป... ลูกน้อง! ซื้อเวลาให้นายของคุณมากขึ้น!",
  ui_story_5079_50791501_115_dialog_content = "กราาาาาา—",
  ui_story_5079_50791501_116_dialog_content = "หนีไปพร้อมกับหินแห่งการล่าหรอ? ผิดคิดใหญ่เลย...",
  ui_story_5079_50791501_117_dialog_content = "ตราบใดที่หัวใจของเรายังเป็นหนึ่งเดียวกัน ระยะทางใด ๆ ระหว่างเราจะทำให้ความผูกพันของเราแข็งแกร่งขึ้นเท่านั้น",
  ui_story_5079_50791501_118_dialog_content = "ฉันจะไม่ยอมให้คุณทำร้ายโปโป้...",
  ui_story_5079_50791501_119_dialog_content = "และฉันจะไม่ปล่อยให้ใครอื่นหนีไปพร้อมกับหินแห่งการล่าของฉัน!",
  ui_story_5079_50791601_1_dialog_content = "<color=#e8d9bb>ตูม, ตูม, ตูม!</color>",
  ui_story_5079_50791601_2_dialog_content = "กร๊าาาา...",
  ui_story_5079_50791601_3_dialog_content = "ไปให้พ้น พวกแกอ่อนแอ!",
  ui_story_5079_50791601_4_dialog_content = "นี่ไม่ได้เลย! ทำไมคุณไล่ตามฉันมาได้เร็วขนาดนี้?",
  ui_story_5079_50791601_5_dialog_content = "<color=#e8d9bb>ฟิ้ว—</color>",
  ui_story_5079_50791601_6_dialog_content = "เอาหนวดสกปรกของคุณออกจากโปโป้นะ เจ้าสัตว์ประหลาด!",
  ui_story_5079_50791601_7_dialog_content = "มัน... มันคือ...คุณ...",
  ui_story_5079_50791601_8_dialog_content = "ขอโทษที, ฉันมาช้า ไม่ต้องห่วง, คุณปลอดภัยแล้ว...",
  ui_story_5079_50791601_9_dialog_content = "ฉัน...ฉันรู้ว่าคุณจะมาช่วยฉัน ฉันไม่เคยสงสัย...ไม่เคยสงสัยเลย...",
  ui_story_5079_50791601_10_dialog_content = "ขอโทษที่ความไม่มีประโยชน์ของฉันทำให้ฉันถูกจับอีกครั้ง พ่อของฉันคือ—",
  ui_story_5079_50791601_11_dialog_content = "เหมือนที่ฉันบอก คุณไม่ต้องกังวลอีกต่อไป... ปล่อยทุกอย่างให้ฉันจัดการเถอะ",
  ui_story_5079_50791601_12_dialog_content = "อย่า... อย่ามามองฉันเหมือนฉันเป็นขยะสิ!",
  ui_story_5079_50791601_13_dialog_content = "ฉันยังไม่ได้โชว์พลังเต็มที่ให้เธอดูเลยนะ!",
  ui_story_5079_50791601_14_dialog_content = "งั้นเหรอครับ? ดีนะ ฉันก็ไม่รังเกียจที่จะไปดูด้วยตัวเองเหมือนกันนะ.",
  ui_story_5079_50791601_15_dialog_content = "ฉันพร้อมที่จะปล่อยชีวิตคุณถ้าคุณแค่คืนหินล่าสัตว์ของฉัน... แต่ตอนนี้ไม่มีแล้ว",
  ui_story_5079_50791601_16_dialog_content = "ถ้าเธอยืนยันที่จะทำแบบนี้ ก็ให้ฉันแสดงพลังเต็มที่ของฉันให้เธอดูสิ!",
  ui_story_5079_50791602_1_dialog_content = "<color=#e8d9bb>ฟิ้วว!</color>",
  ui_story_5079_50791602_2_dialog_content = "เป็นไปไม่ได้! หนวดของฉัน... โอย... คุณทำได้ยังไง...",
  ui_story_5079_50791602_3_dialog_content = "!",
  ui_story_5079_50791602_4_dialog_content = "ไม่... อย่าไปสิ!",
  ui_story_5079_50791602_5_dialog_content = "จบแล้วสำหรับคุณ!",
  ui_story_5079_50791602_6_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5079_50791602_7_dialog_content = "ไม่!",
  ui_story_5079_50791602_8_dialog_content = "!",
  ui_story_5079_50791602_9_dialog_content = "ฮะ? ทำไมคุณดูยินดีจังเลย? พอเถอะน่า!",
  ui_story_5079_50791602_10_dialog_content = "คุณแพกต์ ไม่ควรจะมีความสุขด้วยเหรอ?",
  ui_story_5079_50791602_11_dialog_content = "\"ฉันจะไม่ยอมให้ใครขโมยหินแห่งการล่าของฉันไป!\" นั่นคือที่คุณพูดมาใช่ไหมครับ?",
  ui_story_5079_50791602_12_dialog_content = "?",
  ui_story_5079_50791602_13_dialog_content = "คุณ... คุณคงจะได้ยินผิดฉัน! ฉันไม่ได้พูดอะไรแบบนั้นเลย!",
  ui_story_5079_50791602_14_dialog_content = "อะไรก็ตามที่คุณคิดว่าคุณได้ยิน ลืมมันไปเลยตอนนี้เถอะ!",
  ui_story_5079_50791602_15_dialog_content = "ได้...",
  ui_story_5079_50791602_16_dialog_content = "แต่ดูเหมือนว่าคุณสุดท้ายก็ได้รู้เข้าใจว่าคุณไม่จำเป็นต้องให้ฉันสั่งการพลังของคุณ",
  ui_story_5079_50791602_17_dialog_content = "แล้วทำไมยังยุ่งยากที่จะพาฉันกลับ? ฉันสามารถหยุดตามคุณได้เสมอถ้าคุณจริงจังต้องการ...",
  ui_story_5079_50791602_18_dialog_content = "ฮา?",
  ui_story_5079_50791602_19_dialog_content = "เหตุผลเดียวที่ทุกอย่างกลายเป็นแย่ลงเพราะฉันได้มอบนายให้กับมอนสเตอร์แครอตโง่นั่น",
  ui_story_5079_50791602_20_dialog_content = "ถ้าอิคลิพไซท์จับตัวคุณได้ ไม่มีใครรู้ว่ามันจะทำให้เกิดปัญหาแบบไหน!",
  ui_story_5079_50791602_21_dialog_content = "...",
  ui_story_5079_50791602_22_dialog_content = "รสนิยมของคุณในการเลือกมาสเตอร์ที่คุณคาดหวังก็แย่เหมือนกัน หมายถึง แครอทหรอ? จริงหรือ? คุณไม่สามารถเลือกอะไรที่มันอยู่รอบ ๆ คุณได้เลย!",
  ui_story_5079_50791602_23_dialog_content = "คนเดียวที่คู่ควรเป็นเจ้านายของคุณคือฉัน—ท่านหญิงที่ยิ่งใหญ่และชนชั้นสูง Lady Pact!",
  ui_story_5079_50791602_24_dialog_content = "เข้าใจมั้ย?",
  ui_story_5079_50791602_25_dialog_content = "...",
  ui_story_5079_50791602_26_dialog_content = "คุณกำลังแกล้งฉันใช่มั้ย? เลิกแสร้งทำเป็นไม่พูดได้แล้ว!",
  ui_story_5079_50791602_27_dialog_content = "ฉันไม่ใช่ แค่ว่า... คุณดูเหมือนขุนนางจริง ๆ ในตอนนี้...",
  ui_story_5079_50791602_28_dialog_content = "อ๊ะ...",
  ui_story_5079_50791602_29_dialog_content = "<size=30>ฉันยังยอมรับคำชมเช่น \"สวยงาม\" และ \"น่ารัก\" นะคะ...</size>",
  ui_story_5079_50791602_30_dialog_content = "ฉันยังไม่แพ้!",
  ui_story_5079_50791602_31_dialog_content = "ฉัน... ฉันจะสร้าง... โลกที่สมบูรณ์แบบสำหรับแครอตทั้งหมด! ที่ไม่มีใครดูถูกฉัน...",
  ui_story_5079_50791602_32_dialog_content = "โลกที่ฉันจะได้รับการต้องการ การยอมรับ... และได้รับอนุญาตให้มีชีวิตอยู่!",
  ui_story_5079_50791602_33_dialog_content = "หลังจากทุกสิ่งที่เกิดขึ้น คุณยังค้างความเคืองครั้นอยู่เหรอ?",
  ui_story_5079_50791602_34_dialog_content = "เราจะต้องทำให้คุณหยุด—",
  ui_story_5079_50791602_35_dialog_content = "ด-<size=45>เดี๋ยวก่อน!</size>",
  ui_story_5079_50791602_36_dialog_content = "?",
  ui_story_5079_50791602_37_dialog_content = "ฉันขอโทษ! ฉันไม่ควรจะทิ้งคุณที่นี่หรือพูดสิ่งที่ไม่ดีทั้งหมดนั้น...",
  ui_story_5079_50791602_38_dialog_content = "คำพูดของฉันทำให้คุณเจ็บปวดใช่มั้ย?",
  ui_story_5079_50791602_39_dialog_content = "มันลำบากใช่ไหม? ที่ต้องอยู่ที่นี่คนเดียวเป็นวันๆ...",
  ui_story_5079_50791602_40_dialog_content = "ไม่มีใครคุย ไม่มีใครต้องการคุณ... ฉันเข้าใจว่ามันรู้สึกยังไง...",
  ui_story_5079_50791602_41_dialog_content = "แต่ถ้าคุณยินดีที่จะให้โอกาสฉันอีกครั้ง...",
  ui_story_5079_50791602_42_dialog_content = "เรา... เราจะเป็นเพื่อนกันได้มั้ยครับ?",
  ui_story_5079_50791602_43_dialog_content = "...",
  ui_story_5079_50791602_44_dialog_content = "ฉันต้องการปลูกคุณในแปลงดินที่อุดมสมบูรณ์และมีแสงแดดมากที่สุดในสวนของเรา",
  ui_story_5079_50791602_45_dialog_content = "ฉันต้องการให้คุณได้รับสารอาหารที่จำเป็นทั้งหมดเพื่อให้คุณเติบโตและแข็งแรง และกลายเป็นแครอตที่ทุกคนต้องการกิน!",
  ui_story_5079_50791602_46_dialog_content = "เอ่อ, โปโป้? การเสนอที่จะกินมันไม่ใช่สิ่งที่ทำให้คนอื่นรู้สึกสบายใจ... คุณไม่อยากให้มันมีชีวิตที่ยาวนานและมีสุขภาพดีหรือไม่?",
  ui_story_5079_50791602_47_dialog_content = "<color=#e8d9bb>ฉัวะ!</color>",
  ui_story_5079_50791602_48_dialog_content = "ปอ... โปโป—",
  ui_story_5079_50791602_49_dialog_content = "นี่หมายความว่า... คุณยกโทษให้ฉันเหรอ?",
  ui_story_5079_50791602_50_dialog_content = "โปโป้!",
  ui_story_5079_50791602_51_dialog_content = "คุณรู้ไหม แครอทก็น่ารักได้นะ...",
  ui_story_5079_50791602_52_dialog_content = "คุณคิดยังไงล่ะ? เราควรลองแครอทอีกครั้งไหม?",
  ui_story_5079_50791602_53_dialog_content = "เอิ่ม... ฉันคิดว่าฉันต้องการเวลาเพิ่มเติมในการคิดเรื่องนั้น",
  ui_story_5079_50791602_54_dialog_content = "(ดังนั้นความคิดของมันเกี่ยวกับชีวิตที่ดีคือการถูกกินโดยคนที่มันชอบ...)",
  ui_story_5079_50791602_55_dialog_content = "(เอ่อ, ตราบใดที่มันทำให้มันเติมเต็ม...)",
  ui_story_5079_50791602_56_dialog_content = "... โปโป?",
  ui_story_5079_50791602_57_dialog_content = "พ่อคะ? อ๊ะ! พยายามอย่าขยับนะคะ! คุณเต็มไปด้วยแผล...",
  ui_story_5079_50791602_58_dialog_content = "ฉันแทบไม่รู้สึกอะไรเลย... การเห็นเธอมีชีวิตและสุขภาพดี นั่นเท่านั้นที่ฉันต้องการ...",
  ui_story_5079_50791602_59_dialog_content = "ทั้งหมดนี้เป็นความผิดของฉัน, โปโป้ ฉันไม่ควรสั่งสอนคุณมากเกินไป... หรือบังคับความคิดของฉันให้คุณ...",
  ui_story_5079_50791602_60_dialog_content = "ฉันหลงไหลในการให้เรามี \"ชีวิตครอบครัวที่เหมาะสม\" มากเกินไป",
  ui_story_5079_50791602_61_dialog_content = "และฉันได้วางภาระของความทะเยอทะยานของฉันไว้บนบ่าของคุณ",
  ui_story_5079_50791602_62_dialog_content = "สุดท้ายแล้วชีวิตของฉันก็ไม่มีอะไรมากนัก ฉันทำอะไรไม่ได้นอกจากเสียสูญอย่างต่อเนื่อง ฉันยัง...",
  ui_story_5079_50791602_63_dialog_content = "ฉันยังสูญเสียคนที่รักที่สุดในชีวิต คือแม่ของคุณ... ทุกอย่างเกิดขึ้นเพราะฉันไม่สามารถปกป้องเธอได้...",
  ui_story_5079_50791602_64_dialog_content = "พ่อ... ตลอดเวลานี้ คุณได้ซ่อนความเจ็บปวดเกี่ยวกับการสูญเสียแม่ของฉัน...",
  ui_story_5079_50791602_65_dialog_content = "และคราวนี้ ฉันล้มเหลวในการปกป้องคุณ...",
  ui_story_5079_50791602_66_dialog_content = "เมื่อคุณหนีออกจากบ้าน ฉันก็ไม่สามารถหยุดสงสัยเรื่องหนึ่งได้—ฉันได้ให้อะไรกับครอบครัวของฉันอย่างแน่นอนหรือ?",
  ui_story_5079_50791602_67_dialog_content = "มันไม่ใช่อะไรมากกว่าความทรงจำที่เจ็บปวดเหรอ?",
  ui_story_5079_50791602_68_dialog_content = "ทั้งหมดที่ฉันต้องการคือการกลายเป็นครอบครัวพ่อค้าที่มั่งคั่งในวันหนึ่ง และได้รับประสานมื้ออาหารที่โต๊ะเดียวกับชนชั้นสูงของลูโมโพลิส",
  ui_story_5079_50791602_69_dialog_content = "ดูคุณโตขึ้นและกลายเป็นดวงดาวที่ส่องแสงและดึงดูดสายตาของทุกคน รวมถึงขุนนาง...",
